import pandas as pd
import re
from datetime import datetime

def run(inputs: dict[str, pd.DataFrame]) -> dict[str, pd.DataFrame]:
    raw_payments = inputs["raw_payments"].copy()

    # Initialize reject tracking
    rejects = []
    valid_indices = []

    for idx, row in raw_payments.iterrows():
        row_num = row['row_num']
        reject_reason = None

        # R1: MISSING_ID
        payment_id = row['payment_id']
        if pd.isna(payment_id) or (isinstance(payment_id, str) and payment_id.strip() == ''):
            reject_reason = 'MISSING_ID'

        # R2: BAD_AMOUNT
        if reject_reason is None:
            amount_txt = row['amount_txt']
            if pd.isna(amount_txt):
                reject_reason = 'BAD_AMOUNT'
            else:
                amount_str = str(amount_txt).strip()
                # Legacy number: optional +/-, one or more digits, optional .DD
                pattern = r'^[+-]?\d+(\.\d{1,2})?$'
                if not re.match(pattern, amount_str):
                    reject_reason = 'BAD_AMOUNT'

        # R3: NON_POSITIVE
        if reject_reason is None:
            try:
                amount_val = float(str(row['amount_txt']).strip())
                if amount_val <= 0:
                    reject_reason = 'NON_POSITIVE'
            except:
                reject_reason = 'BAD_AMOUNT'

        # R4: BAD_CURRENCY
        if reject_reason is None:
            currency = row['currency']
            if pd.isna(currency):
                reject_reason = 'BAD_CURRENCY'
            else:
                currency_upper = str(currency).strip().upper()
                if currency_upper not in ['USD', 'EUR', 'GBP']:
                    reject_reason = 'BAD_CURRENCY'

        # R5: BAD_DATE
        if reject_reason is None:
            pay_date_txt = row['pay_date_txt']
            if pd.isna(pay_date_txt):
                reject_reason = 'BAD_DATE'
            else:
                date_str = str(pay_date_txt).strip()
                # Must be exactly YYYY-MM-DD
                if not re.match(r'^\d{4}-\d{2}-\d{2}$', date_str):
                    reject_reason = 'BAD_DATE'
                else:
                    try:
                        datetime.strptime(date_str, '%Y-%m-%d')
                    except ValueError:
                        reject_reason = 'BAD_DATE'

        if reject_reason is not None:
            rejects.append({'row_num': row_num, 'reject_reason': reject_reason})
        else:
            valid_indices.append(idx)

    # Build valid_payments from non-rejected rows
    valid_rows = raw_payments.loc[valid_indices].copy()

    # R6: DUPLICATE - keep only the row with lowest row_num per trimmed payment_id
    if len(valid_rows) > 0:
        valid_rows['payment_id_trimmed'] = valid_rows['payment_id'].str.strip()
        # Group by trimmed payment_id and find the row with minimum row_num in each group
        min_row_num_per_id = valid_rows.groupby('payment_id_trimmed', as_index=False)['row_num'].min()
        min_row_num_per_id.columns = ['payment_id_trimmed', 'min_row_num']

        # Merge to identify duplicates
        valid_rows = valid_rows.merge(min_row_num_per_id, on='payment_id_trimmed', how='left')

        # Identify duplicates (rows where row_num != min_row_num)
        duplicates = valid_rows[valid_rows['row_num'] != valid_rows['min_row_num']].copy()
        for dup_idx, dup_row in duplicates.iterrows():
            rejects.append({'row_num': int(dup_row['row_num']), 'reject_reason': 'DUPLICATE'})

        # Keep only non-duplicate rows
        valid_rows = valid_rows[valid_rows['row_num'] == valid_rows['min_row_num']].copy()
        valid_rows = valid_rows.drop(columns=['payment_id_trimmed', 'min_row_num'])

    # Build output for valid_payments
    if len(valid_rows) > 0:
        valid_payments = pd.DataFrame({
            'payment_id': valid_rows['payment_id'].str.strip(),
            'account_id': valid_rows['account_id'],
            'amount': valid_rows['amount_txt'].str.strip().astype(float),
            'currency': valid_rows['currency'].str.strip().str.upper(),
            'pay_date': valid_rows['pay_date_txt'].str.strip()
        })
    else:
        valid_payments = pd.DataFrame({
            'payment_id': pd.Series(dtype='object'),
            'account_id': pd.Series(dtype='int64'),
            'amount': pd.Series(dtype='float64'),
            'currency': pd.Series(dtype='object'),
            'pay_date': pd.Series(dtype='object')
        })

    # Build output for payment_rejects
    if rejects:
        payment_rejects = pd.DataFrame(rejects)
    else:
        payment_rejects = pd.DataFrame({
            'row_num': pd.Series(dtype='int64'),
            'reject_reason': pd.Series(dtype='object')
        })

    return {
        'valid_payments': valid_payments,
        'payment_rejects': payment_rejects
    }
